@tool
extends Node

func run() -> Dictionary:
	var rep := {"moved": [], "errors": []}
	var f := FileAccess.open("res://tools/gc_cleanup_ops.json", FileAccess.READ)
	var txt := f.get_as_text()
	f.close()
	var ops = JSON.parse_string(txt)
	var d := DirAccess.open("E:/")
	var PROJ := "ghost-company-main/"
	for m in ops.get("move", []):
		var sf := String(m["from"])
		var st := String(m["to"])
		var from_rel := PROJ + sf.substr(6)
		var to_rel := PROJ + st.substr(6)
		if not (d.dir_exists(from_rel) or FileAccess.file_exists(sf)):
			rep["errors"].append({"op": "move", "src": sf, "error": "missing"})
			continue
		var to_parent := to_rel.get_base_dir()
		if not d.dir_exists(to_parent):
			d.make_dir_recursive(to_parent)
		var err2 := d.rename(from_rel, to_rel)
		if err2 == OK:
			rep["moved"].append(sf + " -> " + st)
			if FileAccess.file_exists(sf + ".import"):
				d.rename(from_rel + ".import", to_rel + ".import")
		else:
			rep["errors"].append({"op": "move", "src": sf, "error": str(err2)})
	return rep
